/* @lc app=leetcode id=3748 lang=kotlin */ class Solution { fun tri(l: Long): Long = l * (l + 1) / 2 fun countStableSubarrays(nums: IntArray, queries: Array<IntArray>): LongArray = (nums.indices.filter { it == 0 || nums[it] < nums[it - 1] }).let { st -> (st.drop(1).map { it - 1 } + (nums.size - 1)).let { en -> nums.indices.runningFold(-1) { id, i -> if (i == 0 || nums[i] < nums[i - 1]) id + 1 else id }.drop(1).let { rid -> st.indices.map { tri((en[it] - st[it] + 1).toLong()) }.runningFold(0L) { a, b -> a + b }.let { pre -> queries.map { (l, r) -> if (rid[l] == rid[r]) tri((r - l + 1).toLong()) else tri((en[rid[l]] - l + 1).toLong()) + tri((r - st[rid[r]] + 1).toLong()) + pre[rid[r]] - pre[rid[l] + 1] }.toLongArray() } } } } }